# ✅ **DFS (Depth First Search) – Simple C++ Code**

DFS uses a **stack** (or recursion).  
We’ll use recursion because it’s simplest.

```cpp
#include <iostream>
#include <vector>
using namespace std;

vector<int> adj[100];   // adjacency list
bool visited[100];

void dfs(int node) {
    visited[node] = true;
    cout << node << " ";

    for(int next : adj[node]) {
        if(!visited[next]) {
            dfs(next);
        }
    }
}

int main() {
    int n, e;
    cin >> n >> e;   // n = number of nodes, e = number of edges

    for(int i = 0; i < e; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);   // remove if directed graph
    }

    dfs(0);   // start DFS from node 0
}
```

