# ✅ **DFS in C++ (No vectors, only adjacency matrix)**

```cpp
#include <iostream>
using namespace std;

int adj[100][100];   // adjacency matrix
int visited[100];

void dfs(int node, int n) {
    visited[node] = 1;
    cout << node << " ";

    for(int i = 0; i < n; i++) {
        if(adj[node][i] == 1 && visited[i] == 0) {
            dfs(i, n);
        }
    }
}

int main() {
    int n, e;
    cin >> n >> e;

    // read edges
    for(int i = 0; i < e; i++) {
        int u, v;
        cin >> u >> v;
        adj[u][v] = 1;
        adj[v][u] = 1;   // remove if directed
    }

    dfs(0, n);  // start from node 0
}
```

