# ✅ **BFS in C++ (No vectors, only adjacency matrix + simple queue array)**

```cpp
#include <iostream>
using namespace std;

int adj[100][100];
int visited[100];
int q[100], front = 0, rear = 0;

void bfs(int start, int n) {
    visited[start] = 1;
    q[rear++] = start;

    while(front < rear) {
        int node = q[front++];
        cout << node << " ";

        for(int i = 0; i < n; i++) {
            if(adj[node][i] == 1 && visited[i] == 0) {
                visited[i] = 1;
                q[rear++] = i;
            }
        }
    }
}

int main() {
    int n, e;
    cin >> n >> e;

    for(int i = 0; i < e; i++) {
        int u, v;
        cin >> u >> v;
        adj[u][v] = 1;
        adj[v][u] = 1;   // remove if directed graph
    }

    bfs(0, n);  // start from 0
}
```

